import {rotateToken,tokenSlice,location} from './campaign.mjs';
const mint='#8ee7d4',amber='#efb27e',blue='#86c8f2';
const txt=(x,y,s,size=15,color='#b9cbd5')=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="${color}">${s}</text>`;
const line=(x,y,a,b,color=mint,dash='')=>`<path d="M${x} ${y}L${a} ${b}" fill="none" stroke="${color}" stroke-width="2" ${dash?'stroke-dasharray="6 5"':''}/>`;
const dot=(x,y,c=mint,r=6)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
function shell(body,title){return `<svg viewBox="0 0 700 340" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${title}"><rect width="700" height="340" fill="#111d27"/>${body}</svg>`;}
export function lightView(step){const p=[[160,95],[540,95],[540,235],[160,235]],labels=['W+ · 出发','X+','W−','X−'];let s=txt(350,30,'边界回路的拓扑示意 · 把四段路排成方形，不是四维实景',12);for(let i=0;i<4;i++){const a=p[i],b=p[(i+1)%4];s+=line(...a,...b,i<step?mint:'#3c505e');s+=`<rect x="${a[0]-51}" y="${a[1]-24}" width="102" height="48" rx="9" fill="#21333e" stroke="${i<=step?mint:'#506575'}"/>`+txt(a[0],a[1]+5,labels[i],16);}const q=p[step%4];s+=dot(q[0],q[1]-37,amber,9)+txt(350,170,step===4?'光点回到出发处':`光点走过 ${step} / 4 段`,21,mint)+txt(350,310,'假设光沿边界传播；没有模拟光速、遮挡、门孔或背部成像。',12);return shell(s,'受约束光点的四段闭合路线');}
export function wView(w,shortcut){const x=140+(1-w)*210;let s=txt(350,30,'沿 W 的位置图 · X = Y = Z = 0 · 不是房间的三维摆放',12);s+=`<rect x="140" y="95" width="420" height="125" rx="4" fill="#153438"/>`+line(140,75,140,245,amber)+line(560,75,560,245,blue)+line(105,157,595,157,'#65838b');s+=txt(140,65,'W+ 胞',18,amber)+txt(560,65,'W− 胞',18,blue)+txt(350,120,'四维内部 · 不是第九间胞',17,mint);s+=dot(x,157,mint,10)+txt(x,195,`W = ${w.toFixed(1)}`,18,mint)+txt(140,267,'+1',14)+txt(350,267,'0',14)+txt(560,267,'−1',14);s+=txt(350,302,`当前位置：(0, 0, 0, ${w.toFixed(1)}) · ${location(w)}`,17,mint);if(shortcut)s+=txt(350,330,'内部直达：2　　边界最短：4　　单位约定：棱长 a = 2',12);return shell(s,'W 方向位置与边界内部分类');}
const project=(p,cx)=>[cx+p[0]*83+p[2]*35,178-p[1]*80+p[2]*22];
function tetra(points,cx,full){let s='',p=points.map(v=>project(v,cx));for(let i=0;i<p.length;i++)for(let j=i+1;j<p.length;j++)s+=line(...p[i],...p[j],full?'#7ba1b3':'#8ee7d4');p.forEach((a,i)=>{const c=full?['#efb27e','#abafff','#86c8f2','#8ee7d4'][i]:mint;s+=dot(...a,c,5)+txt(a[0]+12,a[1]-9,full?'ABCD'[i]:'',13,c);});return s;}
export function mirrorView(angle){const ps=rotateToken(angle),slice=tokenSlice(angle);let s=txt(175,35,'XYZ 正交投影',18,mint)+txt(525,35,'与原 w = 0 空间的交集',18,mint)+line(350,55,350,282,'#3c505e');s+=tetra(ps,175,true)+tetra(slice,525,slice.length===4);s+=txt(175,275,angle===90?'投影压成平面 ≠ 物体被压扁':'带标签四面体的投影',12)+txt(525,275,slice.length===4?'完整三维物体在原空间中':'只剩二维三角形切片',12);const a=ps[0];s+=txt(350,312,`A = (${a.map(v=>Math.abs(v)<.0001?'0.00':v.toFixed(2)).join(', ')})`,15,amber)+txt(350,335,`XW = ${angle}°　·　四维中六条边长始终不变`,12);return shell(s,'不对称四面体旋转的投影与切片对比');}
export function enclosureView(stage){const ordinary=stage<2;let s=txt(350,32,ordinary?'普通三维墙：只存在于 w = 0':'完整超立方体边界：max |坐标| = 1',18,mint);s+=txt(350,58,'只画 XW 截面 · 固定 y = z = 0 · 不是完整四维物体',12);const ox=350,oy=180,scale=90;const p=(x,w)=>[ox+x*scale,oy-w*scale];s+=line(150,oy,570,oy,'#354b59')+line(ox,285,ox,80,'#354b59')+txt(590,oy+4,'X',13)+txt(ox,78,'W',13);if(ordinary){s+=line(...p(-1,0),...p(1,0),'#506575',true);s+=dot(...p(-1,0),amber,8)+dot(...p(1,0),amber,8);s+=txt(350,303,'橙色端点：三维房间墙与此截面的交点',12);if(stage===1){const pts=[[0,0],[0,.7],[1.3,.7],[1.3,0]].map(q=>p(...q));s+=`<path d="M${pts.map(q=>q.join(' ')).join(' L')}" stroke="${mint}" fill="none" stroke-width="3"/>`+dot(...pts.at(-1),mint)+txt(350,328,'沿 W 抬离原层，再越过 X = 1；返回原层时已在房外。',12,mint);}else s+=dot(...p(0,0),mint)+txt(350,328,'先试一条离开 w = 0 的绕行路线。',12);}
 else{s+=`<rect x="260" y="90" width="180" height="180" fill="#193a3e55" stroke="${amber}" stroke-width="3"/>`;s+=txt(350,246,'内部',14);const pts=[[0,0],[1,.7],[1.3,.7]].map(q=>p(...q));s+=line(...pts[0],...pts[1],mint)+line(...pts[1],...pts[2],amber,true)+dot(...pts[0],mint)+dot(...pts[1],amber,9)+txt(480,99,'遇到 X+ 边界',13,amber);if(stage===3)s+=dot(...pts[2],blue)+txt(350,305,'到达外部，但已穿越边界；不是无接触绕过。',15,mint);else s+=txt(350,305,'若完整边界不可穿透，路线在这里被挡住。',15,amber);s+=txt(350,330,'虚线表示允许穿越后的路径延长，不代表边界有缺口。',12);}
 return shell(s,'普通三维墙与完整四维边界的 XW 截面对比');}
export function coordinateView(position){let s=txt(350,28,'四个独立坐标的数值图 · 全程处于四维内部',16,mint);const axes=['X','Y','Z','W'];position.forEach((v,i)=>{const y=83+i*56;s+=txt(80,y+5,axes[i],20,['#efb27e','#abafff','#86c8f2',mint][i])+line(150,y,550,y,'#4e6875')+line(350,y-8,350,y+8,'#809ba6')+dot(350+v/0.6*200,y,mint,7)+txt(610,y+5,v.toFixed(1),18,mint);});s+=txt(350,317,`位置 = (${position.map(v=>v.toFixed(1)).join(', ')})　·　max |坐标| ≤ 0.6 < 1`,14,mint);return shell(s,'内部点的四个独立坐标数值图');}
export function obstacleView(step){const pts=[[170,210],[170,114],[530,114],[530,210]],coords=['(−0.6,0,0,0)','(−0.6,0,0,0.4)','(0.6,0,0,0.4)','(0.6,0,0,0)'];let s=txt(350,28,'只画内部的 XW 截面 · y = z = 0 · 不画外边界',15,mint)+line(90,210,610,210,'#526b78')+txt(620,215,'X',14)+txt(105,188,'w = 0',13);s+=`<rect x="305" y="202" width="90" height="16" rx="3" fill="${amber}"/>`+txt(350,250,'三维障碍：|x|≤0.15，|y|、|z|≤0.35，w=0',13,amber);for(let i=0;i<3;i++)s+=line(...pts[i],...pts[i+1],i<step?mint:'#364c59',i>=step);s+=dot(...pts[step],mint,10)+txt(350,87,'旁路高度 W = 0.4，仍在内部',15,mint)+txt(350,295,`第 ${step} / 3 步 · 位置 ${coords[step]}`,17,mint)+txt(350,326,'先离开障碍所在层 → 横向通过 → 返回原层；不穿透障碍。',12);return shell(s,'完全位于四维内部的障碍旁路');}
export function translatedView(offset){const points=rotateToken(0);let s=txt(175,35,'XYZ 正交投影',18,mint)+txt(525,35,'原 w = 0 切片',18,mint)+line(350,55,350,282,'#3c505e')+tetra(points,175,true);if(offset===0)s+=tetra(points,525,true);else s+=txt(525,175,'∅',60,'#7093a4')+txt(525,214,'没有交集',16);s+=txt(175,275,'投影完全不变',14)+txt(525,275,offset===0?'信物整体位于原层':'信物在 W = 0.4，原层为空',13)+txt(350,314,`平移：(x,y,z,0) → (x,y,z,${offset.toFixed(1)})`,17,mint)+txt(350,337,'信物各点始终在四维内部；没有经过任何外边界。',12);return shell(s,'内部平移时不变的投影与变为空集的切片');}
